<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{ $booking->number }} · {{ $business->business_name }}</title><link rel="stylesheet" href="/app.css"><script src="/app.js" defer></script></head><body><div class="print-page"><div class="button-group no-print"><button class="button primary" data-print>Print / Save PDF</button><a class="button" href="{{ route('bookings.show',$booking) }}">Back to booking</a></div><header class="print-header spaced"><div><div class="brand"><img src="{{ $business->logo_path?asset('storage/'.$business->logo_path):'/brand.svg' }}" alt="Business logo"><span>{{ $business->business_name }}</span></div><p class="spaced">{{ $business->address }}<br>{{ $business->email }} · {{ $business->phone }}</p></div><div class="print-title"><strong>{{ $booking->status==='quote'?'QUOTATION':($booking->status==='cancelled'?'CANCELLED':'RENTAL INVOICE') }}</strong><p>{{ $booking->number }}<br>Issued {{ $booking->created_at->format('d M Y') }}</p><x-status :status="$booking->status"/></div></header><div class="print-party"><div><strong>BILL TO</strong><p>{{ $booking->customer->name }}<br>{{ $booking->customer->company }}<br>{{ $booking->customer->address }}<br>{{ $booking->customer->email }}<br>{{ $booking->customer->phone }}</p></div><div><strong>{{ $booking->event_name }}</strong><p>{{ $booking->starts_on->format('d M Y') }} – {{ $booking->ends_on->format('d M Y') }}<br>{{ ucfirst($booking->fulfillment) }} · {{ $booking->venue }}</p></div></div><table><thead><tr><th>DESCRIPTION</th><th>QTY</th><th>DAYS</th><th>DAILY RATE</th><th>AMOUNT</th></tr></thead><tbody>@foreach($booking->items as $i)<tr><td>{{ $i->name }}</td><td>{{ $i->quantity }}</td><td>{{ $i->days }}</td><td><x-money :amount="$i->daily_rate"/></td><td><x-money :amount="$i->total"/></td></tr>@endforeach</tbody></table><div class="totals print-summary"><div><span>Subtotal</span><x-money :amount="$booking->subtotal"/></div><div><span>Discount</span><span>− <x-money :amount="$booking->discount"/></span></div><div><span>Delivery / service</span><x-money :amount="$booking->delivery_fee"/></div><div><span>Tax ({{ $booking->tax_bps/100 }}%)</span><x-money :amount="$booking->tax"/></div><div><span>Return fees, tax-inclusive</span><x-money :amount="$booking->return_fee"/></div><div class="total"><span>Total</span><x-money :amount="$booking->total"/></div><div><span>Rental paid, net</span><x-money :amount="$booking->netPaid()"/></div><div class="balance"><span>Balance due</span><x-money :amount="$booking->balance()"/></div><div><span>Refundable deposit required</span><x-money :amount="$booking->deposit_required"/></div><div><span>Refundable deposit held</span><x-money :amount="$booking->depositHeld()"/></div></div>@if($booking->payments->isNotEmpty())<h3>Payment ledger</h3><table><thead><tr><th>DATE</th><th>TYPE</th><th>METHOD</th><th>REFERENCE</th><th>AMOUNT</th></tr></thead><tbody>@foreach($booking->payments as $p)<tr><td>{{ $p->paid_on }}</td><td>{{ ucwords(str_replace('_',' ',$p->kind)) }}</td><td>{{ ucfirst($p->method) }}</td><td>{{ $p->reference }}</td><td><x-money :amount="$p->amount"/></td></tr>@endforeach</tbody></table>@endif<div class="print-terms"><strong>Terms & rental conditions</strong><br>{{ $business->terms }}<br><br>Rental dates are charged inclusively. Security deposits are refundable and are separate from rental payments.<br>{{ $business->tagline }}</div></div></body></html>
